/**
 * Viewer identity core (design-e2e-identity.md sections 2, 3.2, 3.3, 6, 7;
 * crypto Phase 2, web side).
 *
 * This module owns everything about THIS browser's viewer identity:
 * - VIK (ECDSA P-256 signing key) and VBK (ECDH P-256 box key), generated by
 *   WebCrypto with extractable:false and persisted as CryptoKey objects in
 *   IndexedDB via structured clone. Private key bytes never exist outside
 *   the platform key store: nothing here exports them, and nothing is ever
 *   written to localStorage.
 * - Registration of the public keys with the relay (viewer_register frame,
 *   authorized by the admin channel; the socket itself is owned by useRelay,
 *   which installs a transport into this module).
 * - Challenge-response auth material: beginKeyAuth() mints the client nonce
 *   for the auth frame, answerChallenge() signs the pinned payload
 *   utf8("pi-remote-auth-v1") || utf8(viewerId) || relayNonce || clientNonce.
 *   WebCrypto ECDSA output is already IEEE P1363 (r || s), which is exactly
 *   what the relay verifies.
 * - The account content key (ACK): held as a non-extractable AES-GCM
 *   CryptoKey in IndexedDB, plus a sealed copy (the raw ACK wrapped to this
 *   viewer's own box key) so the passphrase-backup flow can recover the raw
 *   bytes later. Raw ACK bytes otherwise exist only transiently in memory.
 * - ACK delivery: wrapAckGrant() wraps the ACK to a recipient's box public
 *   key with the Phase 1 contract (ECDH -> HKDF-SHA256, salt =
 *   utf8(accountId + ":" + delivererFp + ":" + recipientFp), info =
 *   "pi-remote-ack-wrap-v1", AES-256-GCM, blob {nonce, ct}); acceptAckGrant()
 *   unwraps grants addressed to this viewer. The two directions are byte
 *   compatible with the device-side implementation in the extension.
 * - adminSig: signAdminFrame() signs management frames with the VIK using
 *   the pinned canonicalization (utf8("pi-remote-admin-v1") || utf8(type) ||
 *   utf8(canonicalJson(frame minus adminSig/adminToken/type))).
 *
 * Phase 2 completes the identity system only. Conversation bodies are NOT
 * encrypted yet (that is Phase 3); nothing in this module changes what the
 * relay stores or forwards.
 */

/* ------------------------------------------------------------------ */
/* Byte helpers                                                        */
/* ------------------------------------------------------------------ */

const textEncoder = new TextEncoder()

export function textEncode(text: string): Uint8Array {
  return textEncoder.encode(text)
}

/** Standard base64 (with padding), matching the relay's Buffer encoding. */
export function bytesToBase64(bytes: Uint8Array): string {
  let binary = ""
  for (let i = 0; i < bytes.length; i += 1) binary += String.fromCharCode(bytes[i])
  return btoa(binary)
}

/**
 * Strict base64 decode (the relay's b64buf rule): the input must re-encode
 * to itself once padding is normalized, otherwise it is rejected as null.
 */
export function base64ToBytes(text: unknown): Uint8Array | null {
  if (typeof text !== "string" || !text) return null
  let decoded: string
  try {
    decoded = atob(text)
  } catch {
    return null
  }
  const out = new Uint8Array(decoded.length)
  for (let i = 0; i < decoded.length; i += 1) out[i] = decoded.charCodeAt(i)
  const stripPad = (s: string) => s.replace(/=+$/, "")
  if (stripPad(bytesToBase64(out)) !== stripPad(text)) return null
  return out
}

export function concatBytes(parts: readonly Uint8Array[]): Uint8Array {
  let total = 0
  for (const part of parts) total += part.length
  const out = new Uint8Array(total)
  let offset = 0
  for (const part of parts) {
    out.set(part, offset)
    offset += part.length
  }
  return out
}

export function bytesToHex(bytes: Uint8Array): string {
  let hex = ""
  for (let i = 0; i < bytes.length; i += 1) hex += bytes[i].toString(16).padStart(2, "0")
  return hex
}

/* ------------------------------------------------------------------ */
/* Protocol constants (pinned by protocol/v4.json and the design doc)  */
/* ------------------------------------------------------------------ */

/** Domain separator of the challenge-response auth payload (design 3.3). */
export const AUTH_PAYLOAD_DOMAIN = "pi-remote-auth-v1"
/** Domain separator of the adminSig management-frame payload (design 7). */
export const ADMIN_PAYLOAD_DOMAIN = "pi-remote-admin-v1"
/** HKDF info string of the ACK wrap contract (design 3.2, Phase 1 fixed). */
export const ACK_WRAP_INFO = "pi-remote-ack-wrap-v1"
/**
 * Domain tag of the local sealed ACK copy. This is a storage-local format
 * (the ACK wrapped to this viewer's own box key inside IndexedDB), never a
 * wire format; the tag keeps its HKDF output disjoint from wire wraps.
 */
export const ACK_STORE_INFO = "pi-remote-ack-store-v1"
/** The single-account deployment default, same as the device side. */
export const DEFAULT_ACCOUNT_ID = "admin"
/** ACK size in bytes (design 2.2: 32-byte random content key). */
export const CONTENT_KEY_BYTES = 32
/** Client nonce size for key auth (protocol limit authNonceBytes). */
export const CLIENT_NONCE_BYTES = 32
/** Hex characters of a key fingerprint (SHA-256, first 8 bytes). */
export const FINGERPRINT_CHARS = 16

/* ------------------------------------------------------------------ */
/* Payload builders and fingerprints (pure; byte-parity tested)        */
/* ------------------------------------------------------------------ */

/** Auth signing payload: domain || viewerId || relayNonce || clientNonce, raw concatenation. */
export function authSignPayload(viewerId: string, relayNonce: Uint8Array, clientNonce: Uint8Array): Uint8Array {
  return concatBytes([textEncode(AUTH_PAYLOAD_DOMAIN), textEncode(viewerId), relayNonce, clientNonce])
}

/**
 * Canonical JSON for adminSig, mirroring relay/pairing.js canonicalJson:
 * object keys recursively ascending, arrays keep order, no whitespace.
 */
export function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null"
  if (Array.isArray(value)) return "[" + value.map((item) => canonicalJson(item)).join(",") + "]"
  const record = value as Record<string, unknown>
  const parts: string[] = []
  for (const key of Object.keys(record).sort()) parts.push(JSON.stringify(key) + ":" + canonicalJson(record[key]))
  return "{" + parts.join(",") + "}"
}

/**
 * adminSig signing payload for a management frame: the frame minus its
 * adminSig / adminToken / type fields, canonicalized (relay/pairing.js
 * adminPayload is the reference implementation).
 */
export function adminSignPayload(frame: Record<string, unknown>): Uint8Array {
  const rest: Record<string, unknown> = {}
  for (const key of Object.keys(frame)) {
    if (key === "adminSig" || key === "adminToken" || key === "type") continue
    rest[key] = frame[key]
  }
  return concatBytes([
    textEncode(ADMIN_PAYLOAD_DOMAIN),
    textEncode(typeof frame.type === "string" ? frame.type : ""),
    textEncode(canonicalJson(rest)),
  ])
}

async function sha256HexPrefix(subtle: SubtleCrypto, bytes: Uint8Array): Promise<string> {
  const digest = new Uint8Array(await subtle.digest("SHA-256", bytes as BufferSource))
  return bytesToHex(digest).slice(0, FINGERPRINT_CHARS)
}

/** Key fingerprint of an spki public key: SHA-256 hex, first 8 bytes (relay/util.js keyFingerprint). */
export function keyFingerprintOfSpki(spkiDer: Uint8Array, subtle?: SubtleCrypto): Promise<string> {
  const cryptoSubtle = subtle ?? globalThis.crypto?.subtle
  if (!cryptoSubtle) return Promise.reject(new Error("WebCrypto is not available"))
  return sha256HexPrefix(cryptoSubtle, spkiDer)
}

/** ACK fingerprint: SHA-256 of the raw ACK bytes, first 8 bytes hex (ackFp reconciliation). */
export function ackFingerprintOf(ack: Uint8Array, subtle?: SubtleCrypto): Promise<string> {
  const cryptoSubtle = subtle ?? globalThis.crypto?.subtle
  if (!cryptoSubtle) return Promise.reject(new Error("WebCrypto is not available"))
  return sha256HexPrefix(cryptoSubtle, ack)
}

/* ------------------------------------------------------------------ */
/* Key-value storage (IndexedDB in the browser, shims in tests)        */
/* ------------------------------------------------------------------ */

/**
 * Minimal async record store. Values must survive a structured clone:
 * CryptoKey objects are stored directly (browsers clone them into
 * IndexedDB; the key material itself stays inside the platform).
 */
export interface IdentityKvStore {
  get(key: string): Promise<unknown>
  put(key: string, value: unknown): Promise<void>
  remove(key: string): Promise<void>
}

const IDB_NAME = "pi-remote-viewer-identity"
const IDB_STORE = "kv"

/** IndexedDB-backed store: one database, one object store, out-of-line keys. */
export function indexedDbIdentityStore(factory: IDBFactory): IdentityKvStore {
  let dbPromise: Promise<IDBDatabase> | null = null
  const open = (): Promise<IDBDatabase> => {
    if (!dbPromise) {
      dbPromise = new Promise<IDBDatabase>((resolve, reject) => {
        const request = factory.open(IDB_NAME, 1)
        request.onupgradeneeded = () => {
          if (!request.result.objectStoreNames.contains(IDB_STORE)) request.result.createObjectStore(IDB_STORE)
        }
        request.onsuccess = () => resolve(request.result)
        request.onerror = () => reject(request.error ?? new Error("IndexedDB open failed"))
      })
    }
    return dbPromise
  }
  const run = async <T>(mode: IDBTransactionMode, op: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> => {
    const db = await open()
    return new Promise<T>((resolve, reject) => {
      const tx = db.transaction(IDB_STORE, mode)
      const request = op(tx.objectStore(IDB_STORE))
      request.onsuccess = () => resolve(request.result)
      request.onerror = () => reject(request.error ?? new Error("IndexedDB request failed"))
      tx.onerror = () => reject(tx.error ?? new Error("IndexedDB transaction failed"))
    })
  }
  return {
    get: (key) => run("readonly", (store) => store.get(key)),
    put: async (key, value) => {
      await run("readwrite", (store) => store.put(value, key))
    },
    remove: async (key) => {
      await run("readwrite", (store) => store.delete(key))
    },
  }
}

/**
 * In-memory store with structured-clone semantics on both write and read.
 * Used by tests; also the reason the core never assumes IndexedDB-only
 * behavior from its store.
 */
export function memoryIdentityStore(): IdentityKvStore {
  const map = new Map<string, unknown>()
  return {
    get: async (key) => {
      const value = map.get(key)
      return value === undefined ? undefined : structuredClone(value)
    },
    put: async (key, value) => {
      map.set(key, structuredClone(value))
    },
    remove: async (key) => {
      map.delete(key)
    },
  }
}

/* ------------------------------------------------------------------ */
/* Platform injection                                                  */
/* ------------------------------------------------------------------ */

export interface IdentityPlatform {
  subtle: SubtleCrypto
  randomBytes: (length: number) => Uint8Array
  store: IdentityKvStore
}

/** Browser platform: WebCrypto + IndexedDB. Null when either is missing. */
export function browserIdentityPlatform(): IdentityPlatform | null {
  const cryptoObject = (globalThis as { crypto?: Crypto }).crypto
  const idb = (globalThis as { indexedDB?: IDBFactory }).indexedDB
  if (!cryptoObject?.subtle || !idb) return null
  return {
    subtle: cryptoObject.subtle,
    randomBytes: (length) => cryptoObject.getRandomValues(new Uint8Array(length)),
    store: indexedDbIdentityStore(idb),
  }
}

/* ------------------------------------------------------------------ */
/* Transport (installed by useRelay, which owns the socket)            */
/* ------------------------------------------------------------------ */

/**
 * The socket side of identity operations. useRelay installs an
 * implementation whose closures read the live channel and admin token;
 * this module never touches a WebSocket itself.
 *
 * sendAdminCommand sends one management frame and resolves with the ack
 * payload (`data` of the ack frame), rejecting with a coded error on a
 * failure ack or timeout. The implementation attaches the current
 * adminToken when the frame carries no adminSig; the token field is
 * excluded from the adminSig canonical form, so attaching it after
 * signing is safe.
 *
 * requestViewerList sends a list_viewers frame and resolves with the
 * viewer_list reply frame (its `id` echo routes the reply).
 */
export interface ViewerIdentityTransport {
  sendAdminCommand(frame: Record<string, unknown>): Promise<unknown>
  requestViewerList(frame: Record<string, unknown>): Promise<unknown>
}

let installedTransport: ViewerIdentityTransport | null = null

/** Install (or clear, with null) the transport used by the facade below. */
export function setViewerIdentityTransport(transport: ViewerIdentityTransport | null): void {
  installedTransport = transport
}

function requireTransport(): ViewerIdentityTransport {
  if (!installedTransport) throw new Error("身份通道尚未连接：请先连接中转服务，再进行身份登记或名册操作")
  return installedTransport
}

/* ------------------------------------------------------------------ */
/* Stored records                                                      */
/* ------------------------------------------------------------------ */

interface StoredIdentity {
  v: 1
  viewerId: string
  signKey: CryptoKey
  boxKey: CryptoKey
  signPub: string
  boxPub: string
  keyFp: string
  registered: boolean
  admin: boolean
  accountId: string | null
  createdAt: number
}

interface StoredAckEntry {
  key: CryptoKey
  fp: string
  /** The raw ACK sealed to this viewer's own box key (storage-local wrap). */
  sealedEphemeralPub: string
  sealedNonce: string
  sealedCt: string
  backedUpAt: number | null
  updatedAt: number
}

interface StoredAckBook {
  v: 1
  byAccount: Record<string, StoredAckEntry>
}

const IDENTITY_RECORD_KEY = "identity.v1"
const ACK_RECORD_KEY = "ack.v1"

/* ------------------------------------------------------------------ */
/* Public state snapshot                                               */
/* ------------------------------------------------------------------ */

export interface ViewerIdentityState {
  /** Platform + storage usable at all (WebCrypto and IndexedDB present). */
  available: boolean
  /** VIK/VBK exist locally. */
  hasIdentity: boolean
  /** The relay roster holds this identity (per the local binding record). */
  registered: boolean
  viewerId: string | null
  /** Fingerprint of the VIK signing key (16 hex chars). */
  keyFp: string | null
  /** Bound account id; null until learned (operations default to "admin"). */
  accountId: string | null
  /** The roster row carries the admin flag (adminSig-capable). */
  admin: boolean
  /** An ACK is held for the bound account. */
  hasAck: boolean
  ackFp: string | null
  /** A passphrase backup was created from this browser. */
  backedUp: boolean
  backedUpAt: number | null
  /** Conflicting ACK fingerprints while the account diverges, else null. */
  keyMismatch: string[] | null
  /** Last auth/operation failure code worth surfacing, else null. */
  lastError: string | null
}

export const EMPTY_VIEWER_IDENTITY_STATE: ViewerIdentityState = {
  available: false,
  hasIdentity: false,
  registered: false,
  viewerId: null,
  keyFp: null,
  accountId: null,
  admin: false,
  hasAck: false,
  ackFp: null,
  backedUp: false,
  backedUpAt: null,
  keyMismatch: null,
  lastError: null,
}

/** A normalized ACK delivery grant (fields already cleaned by the caller). */
export interface AckGrantInput {
  /** Recipient fingerprint; when present it must equal this viewer's keyFp. */
  to?: string
  /** Granter fingerprint (relay-stamped from the granter's roster row). */
  from: string
  /** Granter box public key (spki base64, relay-stamped). */
  fromBoxPub: string
  /** Account the ACK belongs to; defaults to the bound account. */
  accountId?: string
  blob: { nonce?: unknown; ct?: unknown }
}

/* ------------------------------------------------------------------ */
/* The core                                                            */
/* ------------------------------------------------------------------ */

export class ViewerIdentityCore {
  private readonly platform: IdentityPlatform
  private identity: StoredIdentity | null = null
  private ackBook: StoredAckBook = { v: 1, byAccount: {} }
  /** Raw ACK bytes, memory only; repopulated by unsealing on demand. */
  private readonly rawAckCache = new Map<string, Uint8Array>()
  /** Client nonce of the in-flight key-auth attempt (single use). */
  private pendingClientNonce: Uint8Array | null = null
  private mismatchFps: string[] | null = null
  private lastError: string | null = null

  private constructor(platform: IdentityPlatform) {
    this.platform = platform
  }

  /** Load (or initialize empty) a core on the given platform. */
  static async load(platform: IdentityPlatform): Promise<ViewerIdentityCore> {
    const core = new ViewerIdentityCore(platform)
    const identityRaw = await platform.store.get(IDENTITY_RECORD_KEY)
    if (identityRaw && typeof identityRaw === "object") {
      const record = identityRaw as StoredIdentity
      if (record.viewerId && record.signKey && record.boxKey && record.signPub && record.boxPub) core.identity = record
    }
    const ackRaw = await platform.store.get(ACK_RECORD_KEY)
    if (ackRaw && typeof ackRaw === "object") {
      const book = ackRaw as StoredAckBook
      if (book.byAccount && typeof book.byAccount === "object") core.ackBook = { v: 1, byAccount: book.byAccount }
    }
    return core
  }

  /** The account operations apply to: the learned binding, else the default. */
  accountId(): string {
    return this.identity?.accountId || DEFAULT_ACCOUNT_ID
  }

  snapshot(): ViewerIdentityState {
    const identity = this.identity
    const entry = identity ? this.ackBook.byAccount[this.accountId()] : undefined
    return {
      available: true,
      hasIdentity: !!identity,
      registered: !!identity?.registered,
      viewerId: identity?.viewerId ?? null,
      keyFp: identity?.keyFp ?? null,
      accountId: identity?.accountId ?? null,
      admin: !!identity?.admin,
      hasAck: !!entry,
      ackFp: entry?.fp ?? null,
      backedUp: !!entry?.backedUpAt,
      backedUpAt: entry?.backedUpAt ?? null,
      keyMismatch: this.mismatchFps,
      lastError: this.lastError,
    }
  }

  /* ---------------- key generation and registration ---------------- */

  /** Generate VIK + VBK and persist them (unregistered) when missing. */
  async ensureKeys(): Promise<void> {
    if (this.identity) return
    const { subtle } = this.platform
    const signPair = await subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, false, ["sign", "verify"])
    const boxPair = await subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, false, ["deriveBits"])
    const signPubDer = new Uint8Array(await subtle.exportKey("spki", signPair.publicKey))
    const boxPubDer = new Uint8Array(await subtle.exportKey("spki", boxPair.publicKey))
    const viewerId = "vw-" + bytesToHex(this.platform.randomBytes(12))
    this.identity = {
      v: 1,
      viewerId,
      signKey: signPair.privateKey,
      boxKey: boxPair.privateKey,
      signPub: bytesToBase64(signPubDer),
      boxPub: bytesToBase64(boxPubDer),
      keyFp: await keyFingerprintOfSpki(signPubDer, subtle),
      registered: false,
      admin: false,
      accountId: null,
      createdAt: Date.now(),
    }
    await this.platform.store.put(IDENTITY_RECORD_KEY, this.identity)
  }

  /** Public registration material, or null before keys exist. */
  registrationInfo(): { viewerId: string; signPub: string; boxPub: string; keyFp: string } | null {
    if (!this.identity) return null
    const { viewerId, signPub, boxPub, keyFp } = this.identity
    return { viewerId, signPub, boxPub, keyFp }
  }

  /**
   * Enable flow: ensure keys, register them with the relay through the
   * transport (admin channel), and persist the binding from the ack data
   * ({viewerId, keyFp, admin}). The first viewer of an account registers
   * with admin:true -- the admin gate, not this flag, is what authorizes
   * the registration itself.
   */
  async enable(transport: ViewerIdentityTransport): Promise<ViewerIdentityState> {
    await this.ensureKeys()
    const info = this.registrationInfo()
    if (!info) throw new Error("身份密钥生成失败")
    const frame: Record<string, unknown> = {
      type: "viewer_register",
      viewerId: info.viewerId,
      signPub: info.signPub,
      boxPub: info.boxPub,
      admin: true,
    }
    const data = (await transport.sendAdminCommand(frame)) as Record<string, unknown> | null
    if (this.identity) {
      this.identity.registered = true
      if (data && typeof data.admin === "boolean") this.identity.admin = data.admin
      else this.identity.admin = true
      if (data && typeof data.accountId === "string" && data.accountId) this.identity.accountId = data.accountId
      await this.platform.store.put(IDENTITY_RECORD_KEY, this.identity)
    }
    this.lastError = null
    return this.snapshot()
  }

  /** Learn the account binding (from a register ack or auth_result). */
  async bindAccount(accountId: string): Promise<void> {
    if (!this.identity || !accountId || this.identity.accountId === accountId) return
    this.identity.accountId = accountId
    await this.platform.store.put(IDENTITY_RECORD_KEY, this.identity)
  }

  /** Record the outcome of a key-revocation of this viewer (roster-side). */
  async markSelfRevoked(): Promise<void> {
    if (!this.identity) return
    this.identity.registered = false
    this.identity.admin = false
    await this.platform.store.put(IDENTITY_RECORD_KEY, this.identity)
  }

  /**
   * Forget the local identity entirely: keys and ACK copies are wiped.
   * A later enable mints a fresh viewerId and key pair (a revoked signing
   * key must never come back under the same viewerId, design 3.5).
   */
  async forget(): Promise<void> {
    this.identity = null
    this.ackBook = { v: 1, byAccount: {} }
    this.rawAckCache.clear()
    this.pendingClientNonce = null
    this.mismatchFps = null
    await this.platform.store.remove(IDENTITY_RECORD_KEY)
    await this.platform.store.remove(ACK_RECORD_KEY)
  }

  /* ---------------- challenge-response auth ---------------- */

  /**
   * Start a key-auth attempt: returns the auth frame fields, or null when
   * this viewer cannot key-auth (no identity, or not registered). The
   * client nonce is remembered for answerChallenge and is single-use.
   */
  beginKeyAuth(): { viewerId: string; keyFp: string; clientNonce: string } | null {
    if (!this.identity?.registered) return null
    this.pendingClientNonce = this.platform.randomBytes(CLIENT_NONCE_BYTES)
    return {
      viewerId: this.identity.viewerId,
      keyFp: this.identity.keyFp,
      clientNonce: bytesToBase64(this.pendingClientNonce),
    }
  }

  /**
   * Sign the challenge: payload = domain || viewerId || relayNonce ||
   * clientNonce with the VIK; returns the base64 signature (IEEE P1363,
   * WebCrypto's native ECDSA form), or null when no attempt is in flight
   * or the challenge is malformed.
   */
  async answerChallenge(relayNonceB64: string): Promise<string | null> {
    const identity = this.identity
    const clientNonce = this.pendingClientNonce
    this.pendingClientNonce = null
    if (!identity || !clientNonce) return null
    const relayNonce = base64ToBytes(relayNonceB64)
    if (!relayNonce || relayNonce.length < 16 || relayNonce.length > 64) return null
    const payload = authSignPayload(identity.viewerId, relayNonce, clientNonce)
    const signature = await this.platform.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, identity.signKey, payload as BufferSource)
    return bytesToBase64(new Uint8Array(signature))
  }

  /** Drop any in-flight auth attempt state (e.g. after auth succeeded). */
  clearKeyAuthAttempt(): void {
    this.pendingClientNonce = null
  }

  /** Remember an auth/operation failure code for the state snapshot. */
  noteAuthFailure(code: string): void {
    this.lastError = code || "auth_failed"
  }

  /** Record (or clear, with null) the conflicting ACK fingerprints. */
  noteKeyMismatch(ackFps: string[] | null): void {
    this.mismatchFps = ackFps && ackFps.length > 1 ? [...ackFps] : null
    if (this.mismatchFps) this.lastError = "key_mismatch"
    else if (this.lastError === "key_mismatch") this.lastError = null
  }

  /* ---------------- adminSig ---------------- */

  /**
   * Sign a management frame with the VIK (adminSig dual track, design 7).
   * Only possible for a registered, admin-flagged identity; otherwise the
   * frame is returned unchanged and the caller falls back to adminToken.
   * The signer is named by the frame's adminBy field: the relay reads the
   * signer from adminBy (falling back to the connection's bound viewerId)
   * and never treats viewerId as the signer, because on viewer_revoke the
   * viewerId field names the revocation target. adminBy is stamped BEFORE
   * signing, so it sits inside the signed canonical payload exactly as
   * the relay recomputes it.
   */
  async signAdminFrame<T extends Record<string, unknown>>(frame: T): Promise<T> {
    if (!this.identity?.registered || !this.identity.admin) return frame
    const stamped = { ...frame, adminBy: this.identity.viewerId }
    const signature = await this.platform.subtle.sign(
      { name: "ECDSA", hash: "SHA-256" },
      this.identity.signKey,
      adminSignPayload(stamped) as BufferSource,
    )
    return { ...stamped, adminSig: bytesToBase64(new Uint8Array(signature)) }
  }

  /* ---------------- ACK storage ---------------- */

  ackFpFor(accountId: string): string | null {
    return this.ackBook.byAccount[accountId]?.fp ?? null
  }

  hasAckFor(accountId: string): boolean {
    return !!this.ackBook.byAccount[accountId]
  }

  /** The non-extractable AES-GCM key form of the ACK (Phase 3 body crypto). */
  ackCryptoKey(accountId: string): CryptoKey | null {
    return this.ackBook.byAccount[accountId]?.key ?? null
  }

  /**
   * Wrap key for the storage-local sealed copy: ECDH between a fresh
   * ephemeral key pair and one of this viewer's own box keys, HKDF with
   * the store domain tag. direction "seal" derives with the ephemeral
   * private key against our box public key; "unseal" with our box private
   * key against the stored ephemeral public key -- both sides compute the
   * same shared secret.
   */
  private async storeWrapKey(accountId: string, peerBoxKey: CryptoKey, mine: CryptoKey): Promise<CryptoKey> {
    const { subtle } = this.platform
    const shared = new Uint8Array(await subtle.deriveBits({ name: "ECDH", public: peerBoxKey }, mine, 256))
    const ikm = await subtle.importKey("raw", shared as BufferSource, "HKDF", false, ["deriveBits"])
    const bits = await subtle.deriveBits(
      {
        name: "HKDF",
        hash: "SHA-256",
        salt: textEncode(`${ACK_STORE_INFO}:${accountId}:${this.identity?.keyFp ?? ""}`) as BufferSource,
        info: textEncode(ACK_STORE_INFO) as BufferSource,
      },
      ikm,
      256,
    )
    return subtle.importKey("raw", bits, { name: "AES-GCM" }, false, ["encrypt", "decrypt"])
  }

  private async sealAck(accountId: string, ackRaw: Uint8Array): Promise<{ epk: string; nonce: string; ct: string }> {
    const identity = this.identity
    if (!identity) throw new Error("no viewer identity")
    const { subtle } = this.platform
    const ephemeral = await subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, false, ["deriveBits"])
    const myBoxPub = await subtle.importKey("spki", base64ToBytes(identity.boxPub) as BufferSource, { name: "ECDH", namedCurve: "P-256" }, false, [])
    const wrapKey = await this.storeWrapKey(accountId, myBoxPub, ephemeral.privateKey)
    const nonce = this.platform.randomBytes(12)
    const ct = await subtle.encrypt({ name: "AES-GCM", iv: nonce as BufferSource }, wrapKey, ackRaw as BufferSource)
    const epk = new Uint8Array(await subtle.exportKey("spki", ephemeral.publicKey))
    return { epk: bytesToBase64(epk), nonce: bytesToBase64(nonce), ct: bytesToBase64(new Uint8Array(ct)) }
  }

  private async unsealAck(accountId: string, entry: StoredAckEntry): Promise<Uint8Array | null> {
    const identity = this.identity
    if (!identity) return null
    const { subtle } = this.platform
    const epkBytes = base64ToBytes(entry.sealedEphemeralPub)
    const nonce = base64ToBytes(entry.sealedNonce)
    const ct = base64ToBytes(entry.sealedCt)
    if (!epkBytes || !nonce || !ct) return null
    try {
      const ephemeralPub = await subtle.importKey("spki", epkBytes as BufferSource, { name: "ECDH", namedCurve: "P-256" }, false, [])
      const wrapKey = await this.storeWrapKey(accountId, ephemeralPub, identity.boxKey)
      const plain = await subtle.decrypt({ name: "AES-GCM", iv: nonce as BufferSource }, wrapKey, ct as BufferSource)
      const ack = new Uint8Array(plain)
      return ack.length === CONTENT_KEY_BYTES ? ack : null
    } catch {
      return null
    }
  }

  /** Persist an ACK for an account: key form + sealed raw copy + fingerprint. */
  async storeAck(accountId: string, ackRaw: Uint8Array): Promise<string> {
    if (ackRaw.length !== CONTENT_KEY_BYTES) throw new Error("内容钥长度不对（应为 32 字节）")
    if (!this.identity) throw new Error("尚未生成观看端身份，无法存放内容钥")
    const { subtle } = this.platform
    const key = await subtle.importKey("raw", ackRaw as BufferSource, { name: "AES-GCM" }, false, ["encrypt", "decrypt"])
    const fp = await ackFingerprintOf(ackRaw, subtle)
    const sealed = await this.sealAck(accountId, ackRaw)
    const previous = this.ackBook.byAccount[accountId]
    this.ackBook.byAccount[accountId] = {
      key,
      fp,
      sealedEphemeralPub: sealed.epk,
      sealedNonce: sealed.nonce,
      sealedCt: sealed.ct,
      backedUpAt: previous?.fp === fp ? (previous?.backedUpAt ?? null) : null,
      updatedAt: Date.now(),
    }
    await this.platform.store.put(ACK_RECORD_KEY, this.ackBook)
    this.rawAckCache.set(accountId, new Uint8Array(ackRaw))
    return fp
  }

  /** Store an ACK recovered from a passphrase backup (same path as a grant). */
  async importAck(accountId: string, ackRaw: Uint8Array): Promise<string> {
    return this.storeAck(accountId, ackRaw)
  }

  /**
   * Raw ACK bytes for the passphrase-backup flow ONLY. This is the single
   * controlled exit for key material in this module: it exists so the
   * backup agent can wrap the ACK under a user passphrase. Callers must
   * not persist or transmit the returned bytes anywhere else.
   */
  async exportAckForBackup(accountId: string): Promise<Uint8Array | null> {
    const cached = this.rawAckCache.get(accountId)
    if (cached) return new Uint8Array(cached)
    const entry = this.ackBook.byAccount[accountId]
    if (!entry) return null
    const ack = await this.unsealAck(accountId, entry)
    if (ack) this.rawAckCache.set(accountId, new Uint8Array(ack))
    return ack
  }

  /** Record that a passphrase backup covering the current ACK exists. */
  async markBackedUp(accountId: string, at: number): Promise<void> {
    const entry = this.ackBook.byAccount[accountId]
    if (!entry) return
    entry.backedUpAt = at
    await this.platform.store.put(ACK_RECORD_KEY, this.ackBook)
  }

  /* ---------------- ACK delivery (Phase 1 wrap contract) ---------------- */

  /**
   * Derive the wrap key shared with a peer box key. The salt binds the
   * account and BOTH fingerprints (deliverer first, recipient second);
   * swapping them derives a different key, which the tests pin down.
   */
  private async ackWrapKey(peerBoxSpki: Uint8Array, accountId: string, delivererFp: string, recipientFp: string): Promise<CryptoKey> {
    const identity = this.identity
    if (!identity) throw new Error("no viewer identity")
    const { subtle } = this.platform
    const peer = await subtle.importKey("spki", peerBoxSpki as BufferSource, { name: "ECDH", namedCurve: "P-256" }, false, [])
    const shared = new Uint8Array(await subtle.deriveBits({ name: "ECDH", public: peer }, identity.boxKey, 256))
    const ikm = await subtle.importKey("raw", shared as BufferSource, "HKDF", false, ["deriveBits"])
    const bits = await subtle.deriveBits(
      {
        name: "HKDF",
        hash: "SHA-256",
        salt: textEncode(`${accountId}:${delivererFp}:${recipientFp}`) as BufferSource,
        info: textEncode(ACK_WRAP_INFO) as BufferSource,
      },
      ikm,
      256,
    )
    return subtle.importKey("raw", bits, { name: "AES-GCM" }, false, ["encrypt", "decrypt"])
  }

  /**
   * Wrap the held ACK to a recipient's box public key (the deliverer side
   * of the Phase 1 contract; used for pair_approve's contentKeyGrant and
   * for answering content_key_request). Returns the {to, nonce, ct} blob,
   * or null when no ACK is held for the account.
   */
  async wrapAckGrant(accountId: string, recipientFp: string, recipientBoxPubB64: string): Promise<{ to: string; nonce: string; ct: string } | null> {
    const identity = this.identity
    if (!identity?.registered) return null
    const peerSpki = base64ToBytes(recipientBoxPubB64)
    if (!peerSpki || !recipientFp) return null
    const ack = await this.exportAckForBackup(accountId)
    if (!ack) return null
    const wrapKey = await this.ackWrapKey(peerSpki, accountId, identity.keyFp, recipientFp)
    const nonce = this.platform.randomBytes(12)
    const ct = await this.platform.subtle.encrypt({ name: "AES-GCM", iv: nonce as BufferSource }, wrapKey, ack as BufferSource)
    return { to: recipientFp, nonce: bytesToBase64(nonce), ct: bytesToBase64(new Uint8Array(ct)) }
  }

  /**
   * Accept a grant addressed to this viewer: unwrap with the VBK private
   * key under the Phase 1 contract and store the ACK. Any inconsistency
   * (wrong recipient, bad blob, GCM tag failure, wrong length) is a plain
   * false -- grants are never partially applied.
   */
  async acceptAckGrant(grant: AckGrantInput): Promise<boolean> {
    const identity = this.identity
    if (!identity?.registered) return false
    if (grant.to && grant.to !== identity.keyFp) return false
    const granterSpki = base64ToBytes(grant.fromBoxPub)
    const nonce = base64ToBytes(grant.blob?.nonce)
    const ct = base64ToBytes(grant.blob?.ct)
    if (!granterSpki || !nonce || nonce.length !== 12 || !ct || !grant.from) return false
    const accountId = grant.accountId || this.accountId()
    try {
      const wrapKey = await this.ackWrapKey(granterSpki, accountId, grant.from, identity.keyFp)
      const plain = await this.platform.subtle.decrypt({ name: "AES-GCM", iv: nonce as BufferSource }, wrapKey, ct as BufferSource)
      const ack = new Uint8Array(plain)
      if (ack.length !== CONTENT_KEY_BYTES) return false
      await this.storeAck(accountId, ack)
      return true
    } catch {
      return false
    }
  }

  /* ---------------- roster (via transport) ---------------- */

  /** Fetch the authorized-viewer roster; resolves with the viewers array. */
  async listViewers(transport: ViewerIdentityTransport): Promise<unknown> {
    const frame = await this.signAdminFrame<Record<string, unknown>>({ type: "list_viewers" })
    const reply = await transport.requestViewerList(frame)
    if (Array.isArray(reply)) return reply
    if (reply && typeof reply === "object" && Array.isArray((reply as { viewers?: unknown }).viewers)) {
      return (reply as { viewers: unknown }).viewers
    }
    return reply
  }

  /**
   * Revoke one viewer through the admin channel; resolves with the ack
   * data ({closed, ackRotationRequired, hint} per the relay contract).
   * The adminSig track works for any target: signAdminFrame names the
   * signer in adminBy, while the frame's viewerId stays the TARGET. When
   * this identity cannot sign (not registered / not admin), the frame
   * goes out unsigned and the transport attaches the adminToken instead.
   */
  async revokeViewer(transport: ViewerIdentityTransport, targetViewerId: string): Promise<unknown> {
    const frame = await this.signAdminFrame<Record<string, unknown>>({ type: "viewer_revoke", viewerId: targetViewerId })
    const data = await transport.sendAdminCommand(frame)
    if (this.identity && targetViewerId === this.identity.viewerId) await this.markSelfRevoked()
    return data
  }
}

/* ------------------------------------------------------------------ */
/* Default singleton + facade (the settings/backup surface)            */
/* ------------------------------------------------------------------ */

let defaultCorePromise: Promise<ViewerIdentityCore | null> | null = null

/**
 * The shared default core (browser platform). Resolves null when the
 * platform cannot host an identity (no WebCrypto / no IndexedDB, or the
 * store fails to load). useRelay and the facade share this one instance,
 * so auth state and settings state never diverge.
 */
export function getDefaultViewerIdentityCore(): Promise<ViewerIdentityCore | null> {
  if (!defaultCorePromise) {
    const platform = browserIdentityPlatform()
    defaultCorePromise = platform ? ViewerIdentityCore.load(platform).catch(() => null) : Promise.resolve(null)
  }
  return defaultCorePromise
}

/** Fresh core on an explicit platform (tests, non-default storage). */
export function createViewerIdentityCore(platform: IdentityPlatform): Promise<ViewerIdentityCore> {
  return ViewerIdentityCore.load(platform)
}

async function requireCore(): Promise<ViewerIdentityCore> {
  const core = await getDefaultViewerIdentityCore()
  if (!core) throw new Error("当前浏览器不支持观看端身份（缺少 WebCrypto 或 IndexedDB）")
  return core
}

/**
 * Stable facade for the settings / backup surface. Method names are the
 * contract the settings adapter probes; keep them stable.
 */
export const viewerIdentity = {
  /** Current identity state snapshot (see ViewerIdentityState). */
  async getState(): Promise<ViewerIdentityState> {
    const core = await getDefaultViewerIdentityCore()
    return core ? core.snapshot() : EMPTY_VIEWER_IDENTITY_STATE
  },
  /** Generate this browser's identity keys and register them with the relay. */
  async enable(): Promise<ViewerIdentityState> {
    const core = await requireCore()
    return core.enable(requireTransport())
  },
  /** Raw ACK bytes for the passphrase-backup flow only; null when no ACK is held. */
  async exportAck(): Promise<Uint8Array | null> {
    const core = await getDefaultViewerIdentityCore()
    if (!core) return null
    return core.exportAckForBackup(core.accountId())
  },
  /** Store an ACK recovered from a passphrase backup package. */
  async importAck(ack: Uint8Array): Promise<void> {
    const core = await requireCore()
    await core.importAck(core.accountId(), ack)
  },
  /** Record that a passphrase backup was created at the given time. */
  async markBackedUp(at: number): Promise<void> {
    const core = await getDefaultViewerIdentityCore()
    if (core) await core.markBackedUp(core.accountId(), at)
  },
  /** Authorized-viewer roster (raw reply rows) via the admin channel. */
  async listViewers(): Promise<unknown> {
    const core = await requireCore()
    return core.listViewers(requireTransport())
  },
  /** Revoke one viewer by id via the admin channel; resolves with ack data. */
  async revokeViewer(viewerId: string): Promise<unknown> {
    const core = await requireCore()
    return core.revokeViewer(requireTransport(), viewerId)
  },
}

/** Facade alias matching the adapter's probed names. */
export const getViewerIdentityState = viewerIdentity.getState
/** Facade alias matching the adapter's probed names. */
export const enableViewerIdentity = viewerIdentity.enable
/** Facade alias matching the adapter's probed names (backup flow only). */
export const exportAckForBackup = viewerIdentity.exportAck
/** Facade alias matching the adapter's probed names. */
export const importAckFromBackup = viewerIdentity.importAck
